begin;
do $$
declare u uuid:=gen_random_uuid();seller uuid:=gen_random_uuid();mb uuid:=gen_random_uuid();md uuid:=gen_random_uuid();vb uuid:=gen_random_uuid();vd uuid:=gen_random_uuid();p uuid:=gen_random_uuid();pv uuid:=gen_random_uuid();pv_missing uuid:=gen_random_uuid();loc uuid;im1 uuid:=gen_random_uuid();im2 uuid:=gen_random_uuid();req uuid:=gen_random_uuid();work uuid:=gen_random_uuid();cancelled uuid:=gen_random_uuid();j jsonb;n numeric;blocked boolean;begin
 insert into auth.users(id,email) values(u,u::text||'@example.invalid'),(seller,seller::text||'@example.invalid');update arma_private.user_security set requires_password_change=false where user_id in(u,seller);
 insert into public.user_roles(user_id,role_id) select u,id from public.roles where code='admin';insert into public.user_roles(user_id,role_id) select seller,id from public.roles where code='seller';
 insert into public.materials(id,code,name,material_type,created_by) values(mb,mb::text,'UPGRADE TEST BLANK','blank_shirt',u),(md,md::text,'UPGRADE TEST DTF','dtf_transfer',u);
 insert into public.material_variants(id,material_id,sku,size,color,width_cm,height_cm) values(vb,mb,vb::text,'M','Negro',null,null),(vd,md,vd::text,null,null,10,20);
 insert into public.products(id,code,name,created_by) values(p,p::text,'UPGRADE TEST PRODUCT',u);
 insert into public.product_variants(id,product_id,sku,size,color,sale_price) values(pv,p,pv::text,'M','Negro',300),(pv_missing,p,pv_missing::text,'S','Negro',300);
 select id into loc from public.inventory_locations where is_default and is_active;
 insert into public.inventory_balances(location_id,material_variant_id,physical_quantity,average_unit_cost) values(loc,vb,10,100),(loc,vd,20,5);
 insert into public.material_images(id,material_id,storage_path,alt_text,sort_order,is_cover) values(im1,md,'materials/'||im1||'.png','TEST PHOTO',0,true),(im2,md,'materials/'||im2||'.png','TEST PHOTO 2',1,false);
 execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 perform public.catalog_image_action('material',md,im1,'background','black');
 j:=public.catalog_admin_page('material',1,'UPGRADE TEST DTF','active','');if j->'items'->0->'images'->0->>'background'<>'black' then raise exception 'background not saved';end if;
 perform public.catalog_image_action('material',md,im1,'remove');perform public.catalog_image_action('material',md,im1,'remove');
 j:=public.catalog_admin_page('material',1,'UPGRADE TEST DTF','active','');if jsonb_array_length(j->'items'->0->'images')<>1 or j->'items'->0->'images'->0->>'id'<>im2::text then raise exception 'removed image still present';end if;
 perform public.save_material_cost(jsonb_build_object('request_id',req,'variant_id',vd,'method','area','sheet_price',180,'sheet_width_cm',58,'sheet_length_cm',100,'design_width_cm',10,'design_height_cm',20,'waste_percent',10,'apply_inventory',false));
 j:=public.material_cost_profile(vd);if (j->'profile'->>'unit_cost')::numeric<>6.83 or (j->>'inventory_cost')::numeric<>5 then raise exception 'area estimate incorrect or silently changed inventory: %',j;end if;
 perform public.save_material_cost(jsonb_build_object('request_id',req,'variant_id',vd,'method','area','sheet_price',180,'sheet_width_cm',58,'sheet_length_cm',100,'design_width_cm',10,'design_height_cm',20,'waste_percent',10,'apply_inventory',false));
 execute 'reset role';update public.material_variants set height_cm=30 where id=vd;execute 'set local role authenticated';
 j:=public.material_cost_profile(vd);if (j->'profile'->>'unit_cost')::numeric<>10.25 then raise exception 'catalog dimensions do not refresh area cost';end if;
 execute 'reset role';update public.material_variants set height_cm=20 where id=vd;execute 'set local role authenticated';
 perform public.save_material_cost(jsonb_build_object('request_id',gen_random_uuid(),'variant_id',vd,'method','area','sheet_price',200,'sheet_width_cm',28,'sheet_length_cm',100,'design_width_cm',10,'design_height_cm',20,'waste_percent',10,'apply_inventory',true));
 j:=public.material_cost_profile(vd);if (j->'profile'->>'unit_cost')::numeric<>15.72 or (j->>'inventory_cost')::numeric<>15.72 then raise exception 'DTFV or explicit valuation incorrect';end if;
 blocked:=false;begin perform public.save_material_cost(jsonb_build_object('request_id',gen_random_uuid(),'variant_id',vd,'method','area','sheet_price',180,'sheet_width_cm',28,'sheet_length_cm',100,'design_width_cm',40,'design_height_cm',40,'waste_percent',10));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'oversize design accepted';end if;
 blocked:=false;begin perform public.save_material_cost(jsonb_build_object('request_id',gen_random_uuid(),'variant_id',vd,'method','manual','manual_cost','NaN'));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'NaN accepted';end if;
 perform public.workshop_write('recipe',jsonb_build_object('request_id',gen_random_uuid(),'variant_id',pv,'labor_cost',30,'electricity_cost',2,'tape_cost',3,'other_cost',5,'target_margin',40,'lines',jsonb_build_array(jsonb_build_object('material_variant_id',vb,'quantity',1),jsonb_build_object('material_variant_id',vd,'quantity',2))));
 j:=public.workshop_recipe(pv);if (j->'recipe'->>'electricity_cost')::numeric<>2 or (j->'recipe'->>'tape_cost')::numeric<>3 then raise exception 'recipe expenses missing';end if;
 j:=public.workshop_options('ready_product','UPGRADE TEST');if jsonb_array_length(j)<>1 or j->0->>'id'<>pv::text then raise exception 'assembly offers unconfigured recipes';end if;
 j:=public.workshop_recipes_page('missing',1,'UPGRADE TEST');if (j->>'total')::int<>1 or j->'items'->0->>'id'<>pv_missing::text then raise exception 'missing recipe filter incorrect';end if;
 perform public.workshop_write('start',jsonb_build_object('request_id',work,'variant_id',pv,'quantity',3));
 perform public.workshop_write('finish',jsonb_build_object('request_id',gen_random_uuid(),'order_id',work,'quantity',2));
 j:=public.production_board('completed',1,'UPGRADE TEST');if (j->>'total')::int<>1 or (j->'items'->0->>'unit_cost')::numeric<>171.44 then raise exception 'production expense snapshot or final cost incorrect: %',j;end if;
 if j->'items'->0->'inputs'->0->'photo' is null and j->'items'->0->'inputs'->1->'photo' is null then raise exception 'input photos absent';end if;
 perform public.workshop_write('start',jsonb_build_object('request_id',cancelled,'variant_id',pv,'quantity',1));perform public.workshop_write('cancel',jsonb_build_object('request_id',gen_random_uuid(),'order_id',cancelled));
 j:=public.production_board('draft',1,'UPGRADE TEST');if (j->>'total')::int<>0 or (j->'counts'->>'completed')::int<>1 or (j->'counts'->>'cancelled')::int<>1 then raise exception 'board mixed statuses';end if;
 j:=public.business_dashboard(current_date-1,current_date+1);select (x->>'cost')::numeric into n from jsonb_array_elements(j->'prices')x where x->>'id'=pv::text;if n<>171.44 then raise exception 'dashboard ignores expense/reference cost: %',n;end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',seller,'role','authenticated')::text,true);
 blocked:=false;begin perform public.catalog_image_action('material',md,im2,'remove');exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'seller removed material photo';end if;
 blocked:=false;begin perform public.material_cost_profile(vd);exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'seller read material costs';end if;
 blocked:=false;begin perform public.save_material_cost(jsonb_build_object('request_id',gen_random_uuid(),'variant_id',vd,'method','manual','manual_cost',1));exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'seller edited costs';end if;
 blocked:=false;begin perform public.production_board();exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'seller read production';end if;
end $$;
rollback;
